 33	function isHelpToken(token) {
 34	  return token === '-h' || token === '--help';
 35	}
 36	
 37	function isOptionLikeValue(token) {
 38	  if (token === undefined) {
 39	    return true;
 40	  }
 41	
 42	  if (token === '--') {
 43	    return true;
 44	  }
 45	
 46	  if (token.startsWith('--')) {
 47	    return true;
 48	  }
 49	
 50	  return /^-[A-Za-z]/.test(token);
 51	}
 52	
 53	function normalizeLongOptionToken(token) {
 54	  const equalsIndex = token.indexOf('=');
 55	  if (equalsIndex === -1) {
 56	    return { name: token, hasInlineValue: false, value: '' };
 57	  }
 58	
 59	  return {
 60	    name: token.slice(0, equalsIndex),
 61	    hasInlineValue: true,
 62	    value: token.slice(equalsIndex + 1),
 63	  };
 64	}
