 66	export function parseTest4Args(argv = process.argv) {
 67	  const programName = getProgramName(argv);
 68	  const parsed = {};
 69	  const extras = [];
 70	
 71	  for (let index = 2; index < argv.length; index += 1) {
 72	    const token = String(argv[index]);
 73	
 74	    if (isHelpToken(token)) {
 75	      throw new CliExit(0, buildHelp(programName), 'stdout');
 76	    }
 77	
 78	    if (token.startsWith('--')) {
 79	      const optionToken = normalizeLongOptionToken(token);
 80	
 81	      if (Object.prototype.hasOwnProperty.call(OPTION_DEFINITIONS, optionToken.name)) {
 82	        const key = OPTION_DEFINITIONS[optionToken.name];
 83	
 84	        if (optionToken.hasInlineValue) {
 85	          parsed[key] = optionToken.value;
 86	          continue;
 87	        }
 88	
 89	        const nextToken = index + 1 < argv.length ? String(argv[index + 1]) : undefined;
 90	        if (isOptionLikeValue(nextToken)) {
 91	          throw new CliExit(2, buildParseError(programName, `argument ${optionToken.name}: expected one argument`), 'stderr');
 92	        }
 93	
 94	        parsed[key] = nextToken;
 95	        index += 1;
 96	        continue;
 97	      }
 98	
 99	      extras.push(token);
100	      continue;
101	    }
102	
103	    if (token.startsWith('-') && token.length > 1) {
104	      extras.push(token);
105	      continue;
106	    }
107	
108	    extras.push(token);
109	  }
110	
111	  const missing = OPTION_ORDER.filter((name) => !Object.prototype.hasOwnProperty.call(parsed, name));
112	  if (missing.length > 0) {
113	    const formatted = missing.map((name) => `--${name}`).join(', ');
114	    throw new CliExit(2, buildParseError(programName, `the following arguments are required: ${formatted}`), 'stderr');
115	  }
116	
117	  if (extras.length > 0) {
118	    throw new CliExit(2, buildParseError(programName, `unrecognized arguments: ${extras.join(' ')}`), 'stderr');
119	  }
120	
121	  return parsed;
122	}
